import json
import math

def solve():
    with open('/app/data/input.json', 'r') as f:
        data = json.load(f)

    config = data['model_config']
    state_categories = config['state_categories']
    feature_weights = config['feature_weights']
    sensor_priority = config['sensor_priority']

    all_samples = data['training_samples'] + data['test_samples']

    # Compute min/max for non-primary sensors
    non_primary_sensors = ['velocity_rpm', 'torque_nm', 'encoder_reading', 'operational_hours']
    sensor_min = {s: float('inf') for s in non_primary_sensors}
    sensor_max = {s: float('-inf') for s in non_primary_sensors}
    for s in all_samples:
        for key in non_primary_sensors:
            val = s[key]
            if val < sensor_min[key]:
                sensor_min[key] = val
            if val > sensor_max[key]:
                sensor_max[key] = val

    # Compute wear factor
    all_hours = [s['operational_hours'] for s in all_samples]
    hours_min = min(all_hours)
    hours_max = max(all_hours)
    hours_span = hours_max - hours_min
    if hours_span == 0:
        wear_factor = 1.0
    else:
        hours_norm = (hours_max - hours_min) / hours_span
        wear_factor = 1.0 + 0.3 * hours_norm

    def compute_category_score(sample, category_name, category_ranges):
        score = 0.0
        weights = [0.4, 0.3, 0.2, 0.1]
        ranges = [
            category_ranges['temperature_range'],
            category_ranges['vibration_range'],
            category_ranges['current_range'],
            category_ranges['position_error_range']
        ]
        for i, (range_key, w) in enumerate(zip(ranges, weights)):
            lo, hi = range_key
            if i == 0:
                val = sample['motor_temperature_c']
            elif i == 1:
                val = sample['vibration_amplitude_mm']
            elif i == 2:
                val = sample['current_consumption_a']
            elif i == 3:
                val = sample['position_error_mm']
            if lo <= val <= hi:
                score += w
            else:
                if val < lo:
                    dist = lo - val
                else:
                    dist = val - hi
                denom = hi - lo  # denom = critical hi - normal hi
                if denom != 0:
                    score += w * (1.0 - dist / denom)
        return score

    def compute_anomalies(sample):
        anomalies = []
        primary_sensors = ['motor_temperature_c', 'vibration_amplitude_mm',
                           'current_consumption_a', 'position_error_mm']
        for sensor in primary_sensors:
            lo = state_categories['normal'][sensor.replace('_c', '_range')][0]
            hi = state_categories['normal'][sensor.replace('_c', '_range')][1]
            val = sample[sensor]
            if val < lo or val > hi:
                if val < lo:
                    dist = lo - val
                else:
                    dist = val - hi
                denom = state_categories['critical'][sensor.replace('_c', '_range')][1] - state_categories['normal'][sensor.replace('_c', '_range')][0]
                severity = dist / denom
                if severity <= 0.0:
                    severity = 0.0
                if severity > 1.0:
                    severity = 1.0
                anomalies.append({
                    'sensor': sensor,
                    'severity': severity
                })
        return anomalies

    def compute_feature_contributions(sample):
        contribs = {}
        # Primary sensors: normalize using normal.lo to critical.hi
        primary_sensors = ['motor_temperature_c', 'vibration_amplitude_mm',
                           'current_consumption_a', 'position_error_mm']
        for sensor in primary_sensors:
            lo = state_categories['normal'][sensor.replace('_c', '_range')][0]
            hi = state_categories['critical'][sensor.replace('_c', '_range')][1]
            if hi == lo:
                contribs[sensor] = 0.0
            else:
                val = sample[sensor]
                denom = hi - lo  # denom = critical hi - normal lo
                norm_val = (val - lo) / denom
                contribs[sensor] = norm_val

        # Non-primary sensors: normalize using min/max over all samples
        for sensor in non_primary_sensors:
            lo = sensor_min[sensor]
            hi = sensor_max[sensor]
            if hi == lo:
                contribs[sensor] = 0.0
            else:
                val = sample[sensor]
                norm_val = (val - lo) / (hi - lo)
                contribs[sensor] = norm_val

        # Apply wear factor to motor_temperature_c, vibration_amplitude_mm, current_consumption_a
        for sensor in ['motor_temperature_c', 'vibration_amplitude_mm', 'current_consumption_a']:
            contribs[sensor] *= wear_factor
            if contribs[sensor] > 1.0:
                contribs[sensor] = 1.0
            elif contribs[sensor] < 0.0:
                contribs[sensor] = 0.0

        return contribs

    predictions = []
    for sample in all_samples:
        sample_id = sample['sample_id']
        # Compute state match scores for each state
        state_scores = {}
        for state_name in state_categories.keys():
            cat = state_categories[state_name]
            score = compute_category_score(sample, state_name, cat)
            state_scores[state_name] = score

        # Find best state (lexicographic tie-breaking)
        max_score = max(state_scores.values())
        max_states = [s for s, v in state_scores.items() if v == max_score]
        predicted_state = sorted(max_states)[0]

        # Confidence score
        scores_list = sorted(state_scores.values(), reverse=True)
        best = scores_list[0]
        second = scores_list[1] if len(scores_list) > 1 else 0.0
        confidence_score = min(1.0, 0.5 + 2.0 * (best - second))
        confidence_score = round(confidence_score, 4)

        # Anomaly indicators
        anomalies = compute_anomalies(sample)
        # Sort anomalies: by sensor_priority (sensors not listed come after all listed sensors),
        # then by severity descending, then by sensor name ascending
        anomaly_keys = sensor_priority + [s for s in primary_sensors if s not in sensor_priority]
        sorted_anomalies = []
        for a in anomalies:
            pos = None
            for i, ak in enumerate(anomaly_keys):
                if ak == a['sensor']:
                    pos = i
                    break
            if pos is None:
                pos = len(anomaly_keys)
            sorted_anomalies.append((pos, -a['severity'], a['sensor'], a))
        sorted_anomalies.sort()
        sorted_anomalies = [a[3] for a in sorted_anomalies]

        # Feature contributions
        contribs = compute_feature_contributions(sample)
        contribs_rounded = {k: round(v, 4) for k, v in contribs.items()}

        # Check for anomalies count >= 3
        anomaly_count = len(anomalies)
        if anomaly_count >= 3:
            if predicted_state == "normal":
                predicted_state = "degraded"

        predictions.append({
            'sample_id': sample_id,
            'predicted_state': predicted_state,
            'confidence_score': confidence_score,
            'state_match_score': round(max_score, 4),
            'feature_contributions': contribs_rounded,
            'anomaly_indicators': sorted_anomalies
        })

    # Sort predictions by sample_id ascending
    predictions.sort(key=lambda x: x['sample_id'])

    # Build confusion matrix from training samples only
    states = sorted(state_categories.keys())  # normal, degraded, warning, critical
    num_states = len(states)
    confusion = [[0] * num_states for _ in range(num_states)]
    for p in predictions:
        if p['sample_id'].startswith('train'):
            true_state = p['system_state']
            pred_state = p['predicted_state']
            if true_state is not None:
                true_idx = states.index(true_state)
                pred_idx = states.index(pred_state)
                confusion[true_idx][pred_idx] += 1

    # Compute metrics
    total = sum(sum(row) for row in confusion)
    accuracy = round(sum(confusion[i][i] for i in range(num_states)) / total, 4) if total > 0 else 0.0

    precision = [0.0] * num_states
    recall = [0.0] * num_states
    f1_score = [0.0] * num_states

    for i in range(num_states):
        tp = confusion[i][i]
        fp = sum(confusion[j][i] for j in range(num_states) if j != i)
        fn = sum(confusion[i][j] for j in range(num_states) if j != i)

        if tp + fp > 0:
            precision[i] = round(tp / (tp + fp), 4)
        else:
            precision[i] = 0.0

        if tp + fn > 0:
            recall[i] = round(tp / (tp + fn), 4)
        else:
            recall[i] = 0.0

        if (precision[i] + recall[i]) > 0:
            f1_score[i] = round(2 * precision[i] * recall[i] / (precision[i] + recall[i]), 4)
        else:
            f1_score[i] = 0.0

    # Macro-averaged metrics
    macro_precision = round(sum(precision) / num_states, 4)
    macro_recall = round(sum(recall) / num_states, 4)
    macro_f1 = round(sum(f1_score) / num_states, 4)

    # Feature importance: mean absolute contribution per sensor across all samples,
    # multiplied by feature_weights, clamped to [0, 1]
    feature_importance = {}
    for sensor in sorted(feature_weights.keys()):
        mean_abs = 0.0
        for p in predictions:
            if sensor in p['feature_contributions']:
                mean_abs += abs(p['feature_contributions'][sensor])
        mean_abs /= len(predictions)
        weighted = mean_abs * feature_weights[sensor]
        if weighted < 0:
            weighted = 0.0
        if weighted > 1.0:
            weighted = 1.0
        feature_importance[sensor] = round(weighted, 4)

    # Sort feature_importance by importance descending, then by feature name ascending
    sorted_features = sorted(feature_importance.items(), key=lambda x: (-x[1], x[0]))
    feature_importance_list = [{"feature": f[0], "importance": f[1]} for f in sorted_features]

    output = {
        "predictions": predictions,
        "model_performance": {
            "accuracy": accuracy,
            "precision": macro_precision,
            "recall": macro_recall,
            "f1_score": macro_f1,
            "confusion_matrix": {}
        },
        "feature_importance": feature_importance_list
    }

    for i, state_i in enumerate(states):
        output['model_performance']['confusion_matrix'][state_i] = {}
        for j, state_j in enumerate(states):
            output['model_performance']['confusion_matrix'][state_i][state_j] = confusion[i][j]

    with open('/app/data/output.json', 'w') as f:
        json.dump(output, f, indent=None, separators=(',', ':'), ensure_ascii=False)
        f.write('\n')

solve()
